                      Necesita apoyo
                    </button>
                  </div>
                </div>
              )}

              {session.feedback && (
                <div className="flex justify-end mt-6">
                  <button
                    type="button"
                    onClick={() => updateSession({ stage: 'hook', feedback: null, hookStarted: false, hookEnded: false })}
